def is_match_brute(s, p, i, j):
    if j == len(p):
        return i == len(s)
    first_match = i < len(s) and (p[j] == '.' or p[j] == s[i])
    if j + 1 < len(p) and p[j + 1] == '*':
        return (is_match_brute(s, p, i, j + 2)                    # skip: zero occurrences
                or (first_match and is_match_brute(s, p, i + 1, j)))  # extend: one more occurrence
    return first_match and is_match_brute(s, p, i + 1, j + 1)

