bool isMatch(string s, string p) {
    int m = s.size(), n = p.size();
    vector<vector<bool>> dp(m + 1, vector<bool>(n + 1, false));
    dp[0][0] = true;
    for (int j = 1; j <= n; j++) {
        if (p[j - 1] == '*') dp[0][j] = dp[0][j - 2];                   // zero occurrences
    }
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (p[j - 1] == '*') {
                bool skip = dp[i][j - 2];
                bool extend = (p[j - 2] == '.' || p[j - 2] == s[i - 1]) && dp[i - 1][j];
                dp[i][j] = skip || extend;
            } else if (p[j - 1] == '.' || p[j - 1] == s[i - 1]) {
                dp[i][j] = dp[i - 1][j - 1];                                // direct character/dot match
            }
        }
    }
    return dp[m][n];
}
